def E(ident,title,iso,url,start='',end='',**fields):
    e=event(ident,title,COUNTRIES[iso],url,start,end,**fields);e.update(iso=[iso],region=T('Азия','Asia')if iso=='TJK'else T('Европа','Europa'),checked=CHECKED)
    for k,v in dict(entry=GATE,action=GATE,cost=UNKNOWN,language=LANG,note=GATE,reward=AWARD).items():
        if k not in fields:e[k]=v
    e['language_certainty']=e['language'];return e

def profile(i,slug,name,iso,age,themes,lo=None,hi=None,formats=('day',)):
    p=P(i,slug,name,'NPL',age,themes,formats=formats);p.update(iso=iso,country=COUNTRIES[iso],place=COUNTRIES[iso],language=LANG,family_fit=fit(lo,hi),questions=[GATE],editorial_reason=AWARD)
    p['price'].update(amount=None,year=None,unit='unconfirmed',currency='TJS'if iso=='TJK'else'EUR',label=UNKNOWN)
    if iso=='UKR':p['questions'].append(RISK)
    return p

